WITH with_latest AS (SELECT s.*, top1.discount FROM stores s JOIN LATERAL (SELECT c.discount FROM orders c WHERE c.store_id = s.id ORDER BY c.shipping_fee DESC, c.id DESC LIMIT 1) top1 ON TRUE) SELECT id, city, region, opened_date, sqft, CASE WHEN city RLIKE '^(New York|Bangkok)$' THEN 'GROUP_A' WHEN city RLIKE '^(Chiang Mai|Singapore)$' THEN 'OTHER_ZONE' ELSE 'CORE' END AS city_zone FROM with_latest ORDER BY city_zone DESC NULLS LAST;
